-- =====================================================================
-- 0001 Extensions, roles and Row Level Security helpers.
-- Converted from database/reference-schema.sql applying docs/04 rules:
-- UUIDv7 primary keys generated by the application (no DB default), money as
-- bigint minor units, translatable text as jsonb, tenant scoped unique keys,
-- FORCE RLS with USING and WITH CHECK, a non owner app role and a BYPASSRLS
-- super admin role. See ADR-0002, ADR-0007, ADR-0013, ADR-0014.
-- =====================================================================

CREATE EXTENSION IF NOT EXISTS postgis;
CREATE EXTENSION IF NOT EXISTS pgcrypto;

-- Roles. Idempotent so this also runs where a DBA pre-creates them (managed PG).
DO $$
BEGIN
  IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'nxserve_app') THEN
    CREATE ROLE nxserve_app LOGIN PASSWORD 'nxserve_app';
  END IF;
  IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'nxserve_superadmin') THEN
    CREATE ROLE nxserve_superadmin LOGIN PASSWORD 'nxserve_superadmin' BYPASSRLS;
  END IF;
END $$;

GRANT USAGE ON SCHEMA public TO nxserve_app, nxserve_superadmin;

-- Future tables created by the owner grant DML to the app and super admin roles.
ALTER DEFAULT PRIVILEGES IN SCHEMA public
  GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO nxserve_app;
ALTER DEFAULT PRIVILEGES IN SCHEMA public
  GRANT USAGE, SELECT ON SEQUENCES TO nxserve_app;
ALTER DEFAULT PRIVILEGES IN SCHEMA public
  GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO nxserve_superadmin;
ALTER DEFAULT PRIVILEGES IN SCHEMA public
  GRANT USAGE, SELECT ON SEQUENCES TO nxserve_superadmin;

-- The API sets this per transaction from the resolved host or credential.
-- Reading with missing_ok = true yields NULL when unset, so policies deny by default.
CREATE OR REPLACE FUNCTION nx_current_tenant() RETURNS uuid
  LANGUAGE sql STABLE AS $$
    SELECT NULLIF(current_setting('app.tenant_id', true), '')::uuid
$$;

-- Applies the standard strict tenant policy: a row is visible and writable only
-- when its tenant_id equals the request tenant. FORCE RLS so the table owner is
-- subject to it too; only the BYPASSRLS super admin role is exempt.
CREATE OR REPLACE FUNCTION nx_enable_tenant_rls(p_table regclass) RETURNS void
  LANGUAGE plpgsql AS $$
BEGIN
  EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY', p_table);
  EXECUTE format('ALTER TABLE %s FORCE ROW LEVEL SECURITY', p_table);
  EXECUTE format(
    'CREATE POLICY tenant_isolation ON %s USING (tenant_id = nx_current_tenant()) WITH CHECK (tenant_id = nx_current_tenant())',
    p_table);
END $$;

-- For tables that hold both NX global templates (tenant_id IS NULL) and tenant
-- owned copies. Global rows are readable by everyone; writes to global rows are
-- restricted to the super admin (BYPASSRLS) only, never the app role.
CREATE OR REPLACE FUNCTION nx_enable_tenant_or_global_rls(p_table regclass) RETURNS void
  LANGUAGE plpgsql AS $$
BEGIN
  EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY', p_table);
  EXECUTE format('ALTER TABLE %s FORCE ROW LEVEL SECURITY', p_table);
  EXECUTE format(
    'CREATE POLICY tenant_or_global ON %s USING (tenant_id IS NULL OR tenant_id = nx_current_tenant()) WITH CHECK (tenant_id = nx_current_tenant())',
    p_table);
END $$;
